"""Static Introduction and real show-once onboarding in a disposable profile."""
import json


def run_first_use_checks(*, cdp, evaluate, check, wait_for, load, shot):
    e,q=evaluate,json.dumps
    def frame():e('new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)))')
    def viewport(width,height):
        cdp.call('Emulation.setDeviceMetricsOverride',width=width,height=height,deviceScaleFactor=1,mobile=width<=1120)
        cdp.call('Emulation.setTouchEmulationEnabled',enabled=width<=1120,maxTouchPoints=5)
        frame()
        wait_for('document.getElementById("introduction-example").complete&&document.getElementById("introduction-example").naturalWidth>0')
    def reload():
        e('window.firstUseReload=true');cdp.call('Page.reload')
        wait_for('typeof firstUseReload==="undefined"&&document.readyState==="complete"&&typeof firstUse!=="undefined"')
        load();frame()
    def submit(name):
        e(f'fields[0].value={q(name)};form.requestSubmit();applicationCommandTail')
        wait_for('!formSaveBusy&&!dialog.open');frame()
        return e('selectedNode.dataset.entryId')
    e('localStorage.clear()');viewport(390,844);reload()
    check(e('entries.size===0&&nodes.size===0&&physics.particles.size===0&&!firstUse.root.hidden'),'empty Universe shows Introduction without real demo bodies')
    check(e('firstUse.root.querySelector("h2").textContent==="Cosmifold"&&firstUse.root.textContent.includes("Organize anything")'),'Introduction purpose and tone remain')
    check(e('!firstUse.root.querySelector("video,canvas,[autoplay],[controls]")&&typeof FirstUsePreview==="undefined"&&typeof firstUseScene==="undefined"'),'Introduction has no video, autoplay, live example renderer or animation data')
    check(e('firstUse.root.querySelector("picture source")&&document.getElementById("introduction-example").fetchPriority==="high"'),'Introduction has an eager local responsive static image')
    before=e('localStorage.getItem("galaxy:user-data")')
    for width,height in [(1440,1000),(900,1000),(360,800),(390,844),(390,667),(320,568),(430,932),(844,390)]:
        viewport(width,height)
        check(e('document.documentElement.scrollWidth<=innerWidth&&firstUse.root.scrollWidth<=firstUse.root.clientWidth'),f'{width}x{height}: Introduction has no horizontal overflow')
        expected='introduction-example-compact.png' if width<=1120 else 'introduction-example.png'
        check(e(f'document.getElementById("introduction-example").currentSrc.endsWith({q(expected)})'),f'{width}: correct static image variant loads')
        check(e('(()=>{const p=document.getElementById("first-use-preview"),i=document.getElementById("introduction-example"),r=p.getBoundingClientRect(),scale=Math.min(r.width/i.naturalWidth,r.height/i.naturalHeight);return scale<=.6&&getComputedStyle(i).objectFit==="contain"&&parseFloat(getComputedStyle(p).borderRadius)>0})()'),f'{width}: sharp image fits the existing rounded container without cropping')
        columns=e('getComputedStyle(document.querySelector(".first-use-card")).gridTemplateColumns.split(" ").length')
        check(columns==(1 if width<=1120 else 2),f'{width}: existing Introduction column layout remains')
        e('document.getElementById("first-use-create").scrollIntoView({block:"nearest"})');frame()
        check(e('(()=>{const b=document.getElementById("first-use-create"),r=b.getBoundingClientRect();return r.top>=0&&r.bottom<=innerHeight&&b.textContent.includes("Create your first Item")})()'),f'{width}: original CTA stays reachable')
        check(e('document.getElementById("introduction-example").getAnimations({subtree:true}).length===0'),f'{width}: hero has no animation work')
        shot(f'first-use-static-{width}x{height}')
    check(e('localStorage.getItem("galaxy:user-data")')==before,'static example does not write canonical data')
    check(e('(async()=> (await persistence.files.readAll()).length===0)()'),'static example creates no attachment records')
    check(e('hierarchySidebar.rows.size===0&&!tasksView.root.hidden&&tasksView.empty.textContent==="No tasks yet."&&constellations.size===0'),'example stays outside navigation, Tasks and Constellations')
    check(e('(async()=>{const result=await cosmifoldBackup.create(universeRepository),data=await result.blob.arrayBuffer(),magic=new TextEncoder().encode(cosmifoldBackup.magic).length,size=new DataView(data).getUint32(magic+4,true),manifest=JSON.parse(new TextDecoder().decode(new Uint8Array(data,magic+40,size)));return manifest.counts.entries===0&&manifest.attachments.length===0})()'),'Backup contains no example content or image')
    viewport(390,844)
    e('document.getElementById("first-use-help").click()');frame()
    check(e('document.getElementById("help-dialog").open&&document.activeElement.id==="close-help-button"'),'Introduction Help retains native modal focus')
    e('document.getElementById("close-help-button").click()');frame()
    check(e('document.activeElement.id==="first-use-help"&&document.getElementById("introduction-example").naturalWidth>0'),'Help returns to Introduction without media resume logic')
    cdp.call('Emulation.setEmulatedMedia',features=[{'name':'prefers-reduced-motion','value':'reduce'}]);frame()
    check(e('document.getElementById("introduction-example").naturalWidth>0&&!firstUse.root.querySelector("video")'),'reduced-motion users receive the same static experience')
    e('window.dispatchEvent(new Event("pagehide"));window.dispatchEvent(new Event("pageshow"))');frame()
    check(e('document.getElementById("introduction-example").complete'),'page lifecycle return needs no playback or renderer restart')
    e('hierarchySidebar.setCollapsed(false)');frame()
    check(e('getComputedStyle(firstUse.root).visibility==="hidden"'),'mobile drawer still obscures Introduction')
    e('hierarchySidebar.setCollapsed(true);document.getElementById("first-use-create").click()');frame()
    check(e('dialog.open&&document.activeElement.id==="entry-name"'),'CTA opens existing focused creation form')
    e('fields[0].value="";form.requestSubmit()');frame()
    check(e('dialog.open&&entries.size===0&&!firstUse.root.hidden&&firstUse.hint.hidden'),'invalid creation preserves Introduction and onboarding state')
    root=submit('Travel')
    check(e('firstUse.root.hidden&&document.getElementById("introduction-example").isConnected'),'successful creation hides static Introduction without renderer teardown')
    check(e(f'entries.size===1&&selectedNode.dataset.entryId==={q(root)}'),'ordinary CRUD selects the first real Item')
    check(e('!firstUse.hint.hidden&&firstUse.hint.textContent.includes("Tap + to add something inside Travel.")&&firstUse.hint.dataset.anchor==="entry-add-button"'),'first coach still names the Item and anchors to Contents +')
    e('contentInspector.editNotes()');frame()
    check(e('getComputedStyle(firstUse.hint).visibility==="hidden"'),'coach yields to existing inline editor')
    e('document.getElementById("content-cancel-notes").click()');frame()
    e(f'createChildEntry({q(root)})');child=submit('Japan')
    check(e(f'entries.get({q(child)}).parentId==={q(root)}&&selectedNode.dataset.entryId==={q(child)}'),'first child retains normal parentage and selection')
    check(e('!firstUse.hint.hidden&&firstUse.hint.textContent.includes("That\'s a branch")&&persistence.preferences.load().firstUseHints.phase==="done"'),'first child completes existing persisted onboarding phase')
    e('firstUse.hint.querySelector("button").click()')
    check(e('firstUse.hint.hidden&&firstUse.timer===null&&firstUse.coachFrame===null'),'coach dismissal clears positioning and timeout')
    e(f'createChildEntry({q(child)})');submit('Tokyo')
    check(e('firstUse.hint.hidden&&firstUse.root.hidden'),'later creation does not restart hints or Introduction')
    reload()
    check(e('entries.size===3&&firstUse.root.hidden&&firstUse.hint.hidden'),'existing saved data remains ordinary after reload')
    e(f'requestGalaxyArchive({q(root)});document.getElementById("archive-galaxy-form").requestSubmit();applicationCommandTail');wait_for('!archiveBusy');frame()
    check(e('entries.size===0&&archivedEntries.size===3&&firstUse.root.hidden'),'archived data prevents a false empty Introduction')
    check(not cdp.errors,'no static Introduction/onboarding exceptions: '+q(cdp.errors))
